const started=new Date().toISOString(),all=new AbortController(),timer=setTimeout(()=>all.abort(),180000),events=[],phases=[],targets=[],logs=[];
let current=null,continuityBefore=null,continuityAfter=null,summary=null;
const allowedCodes=new Set(['ECONNREFUSED','ECONNRESET','ETIMEDOUT','EHOSTUNREACH','ENETUNREACH','EPIPE','ERR_TLS_CERT_ALTNAME_INVALID','UNABLE_TO_VERIFY_LEAF_SIGNATURE','CERT_HAS_EXPIRED','DEPTH_ZERO_SELF_SIGNED_CERT','ERR_SSL_WRONG_VERSION_NUMBER','ERR_SSL_SSLV3_ALERT_BAD_CERTIFICATE','28P01','28000','57014','08006','CONTROLLED_RECOVERY_D3_SOURCE_HEALTH_UNVERIFIED']);
const allowedNames=new Set(['TimeoutError','AbortError','CredentialsProviderError','InvalidAccessKeyId','SignatureDoesNotMatch','AccessDenied','TypeError','Error','error','NetworkingError','InternalError','NotFound','SlowDown','ServiceUnavailable']);
function safeError(error){const name=allowedNames.has(error?.name)?error.name:'OTHER',code=allowedCodes.has(error?.code)?error.code:'OTHER';const frames=[...String(error?.stack??'').matchAll(/node_modules\/((?:@smithy\/|@aws-sdk\/|pg\/)[A-Za-z0-9._/-]+\.js):([0-9]+):([0-9]+)/g)].slice(0,2).map(m=>({module:m[1],line:Number(m[2]),column:Number(m[3])}));return{name,code,httpStatus:Number.isInteger(error?.$metadata?.httpStatusCode)?error.$metadata.httpStatusCode:null,messageSha256:sha256(Buffer.from(String(error?.message??''))),frames};}
function event(value){if(events.length>=128)throw Error('DIAGNOSTIC_EVENT_LIMIT');events.push({...current,...value});}
const originalConnect=Client.prototype.connect,originalQuery=Client.prototype.query,originalSend=S3Client.prototype.send,originalEmit=net.Socket.prototype.emit,seen=new WeakSet();
Client.prototype.connect=async function(...args){if(!seen.has(this)){seen.add(this);this.on('error',error=>event({phase:'PG_CLIENT_ERROR_EVENT',error:safeError(error)}));}const t=performance.now();try{const r=await originalConnect.apply(this,args);event({phase:'PG_CONNECT',ok:true,elapsedMs:Math.round(performance.now()-t)});return r;}catch(error){event({phase:'PG_CONNECT',ok:false,elapsedMs:Math.round(performance.now()-t),error:safeError(error)});throw error;}};
Client.prototype.query=async function(sql,...args){if(sql!=='SELECT 1 AS one, current_database() AS database, current_user AS "user", current_setting(\'server_version_num\')::integer AS version, ssl FROM pg_stat_ssl WHERE pid = pg_backend_pid()'||args.length)throw Error('DIAGNOSTIC_SQL_REFUSED');const t=performance.now();try{const r=await originalQuery.call(this,sql);event({phase:'PG_FIXED_SELECT',ok:true,elapsedMs:Math.round(performance.now()-t),rowCount:r.rowCount});return r;}catch(error){event({phase:'PG_FIXED_SELECT',ok:false,elapsedMs:Math.round(performance.now()-t),error:safeError(error)});throw error;}};
S3Client.prototype.send=async function(command,options){if(command.constructor.name!=='ListBucketsCommand'||Object.keys(command.input).length)throw Error('DIAGNOSTIC_S3_OPERATION_REFUSED');const t=performance.now();try{const r=await originalSend.call(this,command,options);event({phase:'S3_LIST_BUCKETS',ok:true,elapsedMs:Math.round(performance.now()-t),httpStatus:r.$metadata.httpStatusCode,bucketCount:r.Buckets?.length??0});return r;}catch(error){event({phase:'S3_LIST_BUCKETS',ok:false,elapsedMs:Math.round(performance.now()-t),error:safeError(error)});throw error;}};
net.Socket.prototype.emit=function(name,...args){if(name==='error'&&current&&!this._isStdio)event({phase:'SOCKET_ERROR',error:safeError(args[0])});return originalEmit.call(this,name,...args);};
function classify(error){const code=typeof error?.code==='string'&&/^CONTROLLED_RECOVERY_[A-Z0-9_]{1,110}$/.test(error.code)?error.code:'UNCLASSIFIED';return{code,...d3SourceFailureDetails(error)};}
async function inventory(root){const rows=[];async function visit(path,relative,depth){if(depth>10||rows.length>=256)throw Error('DIAGNOSTIC_INVENTORY_LIMIT');const s=await lstat(path,{bigint:true});if(s.isSymbolicLink())throw Error('DIAGNOSTIC_SYMLINK_REFUSED');rows.push({path:relative,dev:String(s.dev),ino:String(s.ino),mode:String(s.mode),uid:String(s.uid),gid:String(s.gid),nlink:String(s.nlink),size:String(s.size),mtime:String(s.mtimeNs),ctime:String(s.ctimeNs)});if(s.isDirectory())for(const name of(await readdir(path)).sort())await visit(path+'/'+name,relative+'/'+name,depth+1);}
for(const name of['source','keys'])await visit(root+'/'+name,name,0);return{entries:rows.length,sha256:digest(rows)};}
try{
 if(process.getuid()!==1000||process.getgid()!==1000)throw Error('DIAGNOSTIC_OWNER_REFUSED');
 const foundation=await loadD3Foundation(),a=foundation.authority,p=foundation.profile.source_backup,c=foundation.components,state=c.sourceState.readOnlyView(),layoutProvider=c.sourceLayout.readOnlyView();
 continuityBefore=await inventory(a.root);const layout=await layoutProvider.verify(),retained=await state.resources(),stages=await state.stages();if(retained.pendingRoles.length||await state.commandInProgress())throw Error('DIAGNOSTIC_PENDING_COMMAND_REFUSED');
 const configs=d3SourceConfigurations(foundation.developmentActivation,p,layout,state.profileSha256),processRunner=new BoundedD3SourceProcess(),prefix=['--config',foundation.profile.docker.config,'--context','default'];
 async function docker(args,limit=1048576){const r=await processRunner.run({executable:'/usr/bin/docker',argv:[...prefix,...args],cwd:'/home/hexmon/Desktop/DARSHAN-SIGNAGE/darshan-server',timeoutMs:10000,maximumOutputBytes:limit,signal:all.signal});if(r.exitCode!==0)throw Object.assign(Error('DIAGNOSTIC_DOCKER_NONZERO'),{code:'CONTROLLED_RECOVERY_D3_SOURCE_PROCESS_NONZERO'});return r;}
 async function inspect(role){const record=retained.resources.find(x=>x.role===role&&!x.retired);if(!record)throw Error('DIAGNOSTIC_RESOURCE_ABSENT');const r=await docker(['container','inspect',record.id]);const values=JSON.parse(r.stdout.toString('utf8'));if(values.length!==1)throw Error('DIAGNOSTIC_INSPECT_AMBIGUOUS');const raw=values[0],plan=fixedD3SourceDockerPlan(foundation.developmentActivation,p,role,configs[role]),observed=sourceObservation(raw,plan,p);if(digest(observed.resource)!==digest(record)||!observed.running)throw Error('DIAGNOSTIC_OWNERSHIP_CHANGED');
 return {role,id:record.id,identitySha256:record.identitySha256,configurationSha256:record.configurationSha256,image:raw.Image,status:raw.State.Status,running:raw.State.Running,restarting:raw.State.Restarting,dead:raw.State.Dead,oomKilled:raw.State.OOMKilled,exitCode:raw.State.ExitCode,restartCount:raw.RestartCount,pid:raw.State.Pid,startedAt:raw.State.StartedAt,finishedAt:raw.State.FinishedAt,health:raw.State.Health?.Status??null,memoryBytes:String(raw.HostConfig.Memory),memorySwapBytes:String(raw.HostConfig.MemorySwap),nanoCpus:String(raw.HostConfig.NanoCpus),pidsLimit:raw.HostConfig.PidsLimit,readOnlyRootfs:raw.HostConfig.ReadonlyRootfs,ip:observed.ip};}
 for(const role of['postgres','minio','valkey'])targets.push(await inspect(role));
 const base=new NodeD3HealthTransport(),transport={};
 for(const [method,role]of[['pg','postgres'],['s3','minio'],['valkey','valkey']])transport[method]=async input=>{current={role,mode:input.mode,requestTimeoutMs:input.timeoutMs};const t=performance.now();let result;try{result=await base[method](input);return result;}finally{phases.push({...current,elapsedMs:Math.round(performance.now()-t),result:result??{ok:false}});current=null;}};
 const health=new ProtectedD3SourceHealth(a,p,layoutProvider,async(role,id)=>{const target=await inspect(role);if(target.id!==id)throw Error('DIAGNOSTIC_TARGET_CHANGED');},transport);
 const groups=[];
 for(const role of['postgres','minio','valkey']){
  const target=targets.find(t=>t.role===role),t=performance.now();let admission;
  try{await c.sourceExecutor.verifyProbeTargetReadOnly(role,target.id,layoutProvider);admission={ok:true,elapsedMs:Math.round(performance.now()-t)};}catch(error){admission={ok:false,elapsedMs:Math.round(performance.now()-t),...classify(error)};if(admission.code!=='CONTROLLED_RECOVERY_D3_SOURCE_HEADROOM_UNSAFE')throw error;}
  const method={postgres:'postgresTlsSelect',minio:'minioTlsS3',valkey:'valkeyTlsPing'}[role],begin=performance.now();let result;
  try{result={ok:true,value:await health[method]({profile:p,containerId:target.id,timeoutMs:p.health.probe_timeout_ms,signal:all.signal})};}catch(error){result={ok:false,...classify(error)};}
  groups.push({role,targetAdmission:admission,diagnosticProbeGroup:{...result,elapsedMs:Math.round(performance.now()-begin)},authority:'DIAGNOSTIC_ONLY_NOT_PREFIX_ACCEPTANCE'});
 }
 for(const target of targets){const r=await docker(['container','logs','--since','30m','--tail','100','--timestamps',target.id],65536),bytes=Buffer.concat([r.stdout,r.stderr]),text=bytes.toString('utf8'),patterns={AUTH_REJECTION:/password authentication failed|WRONGPASS|invalid username-password|AccessDenied/gi,PG_PLAINTEXT_REJECTION:/no pg_hba.conf entry[^\\n]*(?:no encryption|SSL off)/gi,TLS_PLAINTEXT_REJECTION:/HTTP request[^\\n]*HTTPS server|wrong version number|ssl3_get_record/gi,SERVER_READY:/ready to accept connections|Ready to accept connections|API:/gi,ERROR_OR_FATAL:/\\b(?:ERROR|FATAL)\\b/g};logs.push({role:target.role,id:target.id,bytes:bytes.length,sha256:sha256(bytes),categories:Object.fromEntries(Object.entries(patterns).map(([name,regex])=>[name,[...text.matchAll(regex)].length]))});}
 const after=[];for(const role of['postgres','minio','valkey'])after.push(await inspect(role));
 const finalLayout=await layoutProvider.verify(),finalResources=await state.resources();continuityAfter=await inventory(a.root);
 summary={format:'darshan-d3-read-only-health-diagnosis-v1',status:'DIAGNOSIS_COMPLETED',startedAt:started,completedAt:new Date().toISOString(),uid:process.getuid(),gid:process.getgid(),sourceProfileSha256:digest(foundation.profile),sourceStage:stages.at(-1)?.stage??null,layoutSha256:layout.evidenceSha256,resourceReceiptsSha256:digest(retained.resources),pendingRoles:retained.pendingRoles,targets,groups,phases,events,logs,continuity:{before:continuityBefore,after:continuityAfter,unchanged:digest(continuityBefore)===digest(continuityAfter),layoutUnchanged:digest(layout)===digest(finalLayout),resourcesUnchanged:digest(retained)===digest(finalResources),runtimeStateUnchanged:digest(targets)===digest(after)},prefixRetried:false,seed:false,repair:false,gatesChanged:false};
}catch(error){summary={format:'darshan-d3-read-only-health-diagnosis-v1',status:'DIAGNOSIS_INCOMPLETE',startedAt:started,completedAt:new Date().toISOString(),failure:classify(error),error:safeError(error),targets,phases,events,logs,continuityBefore,continuityAfter,prefixRetried:false,seed:false,repair:false,gatesChanged:false};process.exitCode=2;}
finally{clearTimeout(timer);Client.prototype.connect=originalConnect;Client.prototype.query=originalQuery;S3Client.prototype.send=originalSend;net.Socket.prototype.emit=originalEmit;}
const result=JSON.stringify(summary);if(Buffer.byteLength(result)>32768)throw Error('DIAGNOSTIC_OUTPUT_LIMIT');console.log(result);

