import https from 'node:https';
import { lstat, readdir } from 'node:fs/promises';
import { performance } from 'node:perf_hooks';
import { loadD3Foundation } from './scripts/development/controlled-recovery-d3-foundation.ts';
import { NodeD3HealthTransport, ProtectedD3SourceHealth } from './scripts/development/controlled-recovery-d3-source-health.ts';
import { BoundedD3SourceProcess } from './scripts/development/controlled-recovery-d3-source-process.ts';
import { fixedD3SourceDockerPlan, sourceObservation } from './scripts/development/controlled-recovery-d3-docker.ts';
import { d3SourceConfigurations } from './scripts/development/controlled-recovery-d3-source-services.ts';
import { digest, sha256 } from './src/recovery/controlled-docker/contracts.ts';
const startedAt=new Date().toISOString(),controller=new AbortController(),timer=setTimeout(()=>controller.abort(),60000),rounds=[],calls=[],connections=[];let current=null;
const original=https.Agent.prototype.createConnection;
async function snapshot(root){const rows=[];async function visit(path,relative,depth){if(rows.length>=256||depth>10)throw Error('BOUNDS');const s=await lstat(path,{bigint:true});if(s.isSymbolicLink())throw Error('LINK');rows.push({path:relative,dev:String(s.dev),ino:String(s.ino),mode:String(s.mode),uid:String(s.uid),gid:String(s.gid),nlink:String(s.nlink),size:String(s.size),mtime:String(s.mtimeNs),ctime:String(s.ctimeNs)});if(s.isDirectory())for(const n of(await readdir(path)).sort())await visit(path+'/'+n,relative+'/'+n,depth+1);}for(const n of['source','keys'])await visit(root+'/'+n,n,0);return{entries:rows.length,sha256:digest(rows)};}
let report;
try{
 const f=await loadD3Foundation(),a=f.authority,p=f.profile.source_backup,c=f.components,layoutProvider=c.sourceLayout.readOnlyView(),state=c.sourceState.readOnlyView(),layout=await layoutProvider.verify(),retained=await state.resources(),record=retained.resources.find(x=>x.role==='minio'&&!x.retired);if(!record||retained.pendingRoles.length)throw Error('TARGET');
 const before=await snapshot(a.root),configs=d3SourceConfigurations(f.developmentActivation,p,layout,state.profileSha256),runner=new BoundedD3SourceProcess();
 async function target(){const r=await runner.run({executable:'/usr/bin/docker',argv:['--config',f.profile.docker.config,'--context','default','container','inspect',record.id],cwd:'/home/hexmon/Desktop/DARSHAN-SIGNAGE/darshan-server',timeoutMs:10000,maximumOutputBytes:1048576,signal:controller.signal});if(r.exitCode!==0)throw Error('INSPECT');const values=JSON.parse(r.stdout.toString('utf8'));if(values.length!==1)throw Error('AMBIGUOUS');const o=sourceObservation(values[0],fixedD3SourceDockerPlan(f.developmentActivation,p,'minio',configs.minio),p);if(!o.running||digest(o.resource)!==digest(record))throw Error('IDENTITY');return{role:'minio',id:record.id,restartCount:values[0].RestartCount,oomKilled:values[0].State.OOMKilled,exitCode:values[0].State.ExitCode,startedAt:values[0].State.StartedAt,identitySha256:o.resource.identitySha256};}
 const beforeTarget=await target();
 https.Agent.prototype.createConnection=function(...args){const options=args[0];if(!current||!options||typeof options!=='object'||typeof options.checkServerIdentity!=='function')return original.apply(this,args);const entry={...current,agent:this===https.globalAgent?'GLOBAL':'DEDICATED',checkServerIdentityCalls:0,secureConnected:false,sessionReused:null,authorized:null,peerCertificateSha256:null,closed:false};connections.push(entry);const verify=options.checkServerIdentity;args[0]={...options,checkServerIdentity:(host,cert)=>{entry.checkServerIdentityCalls++;return verify(host,cert);}};const socket=original.apply(this,args);if(socket){socket.once('secureConnect',()=>{try{entry.secureConnected=true;entry.sessionReused=socket.isSessionReused();entry.authorized=socket.authorized;const cert=socket.getPeerCertificate(true);entry.peerCertificateSha256=cert?.raw?sha256(cert.raw):null;}catch{/* bounded observation only */}});socket.once('close',()=>{entry.closed=true;});}return socket;};
 const base=new NodeD3HealthTransport(),transport={pg:async()=>{throw Error('FORBIDDEN');},valkey:async()=>{throw Error('FORBIDDEN');},s3:async input=>{current={round:rounds.length+1,mode:input.mode};const t=performance.now();try{const result=await base.s3(input);calls.push({...current,requestTimeoutMs:input.timeoutMs,elapsedMs:Math.round(performance.now()-t),result});return result;}finally{current=null;}}};
 const health=new ProtectedD3SourceHealth(a,p,layoutProvider,(role,id)=>c.sourceExecutor.verifyProbeTargetReadOnly(role,id,layoutProvider),transport);
 for(let round=1;round<=2;round++){const t=performance.now();try{rounds.push({round,ok:true,evidence:await health.minioTlsS3({profile:p,containerId:record.id,timeoutMs:p.health.probe_timeout_ms,signal:controller.signal}),elapsedMs:Math.round(performance.now()-t)});}catch(error){rounds.push({round,ok:false,code:typeof error?.code==='string'?error.code:'UNCLASSIFIED',elapsedMs:Math.round(performance.now()-t)});}await new Promise(resolve=>setImmediate(resolve));}
 const afterTarget=await target(),afterLayout=await layoutProvider.verify(),afterResources=await state.resources(),after=await snapshot(a.root);
 report={format:'darshan-d3-minio-two-pass-health-diagnosis-v1',startedAt,completedAt:new Date().toISOString(),status:'COMPARISON_COMPLETED',node:process.version,sourceProfileSha256:digest(f.profile),target:beforeTarget,expectedCertificateSha256:layout.certificates.minio,globalAgent:{keepAlive:https.globalAgent.keepAlive,maxCachedSessions:https.globalAgent.maxCachedSessions},rounds,calls,connections,continuity:{before,after,unchanged:digest(before)===digest(after),targetUnchanged:digest(beforeTarget)===digest(afterTarget),layoutUnchanged:digest(layout)===digest(afterLayout),resourcesUnchanged:digest(retained)===digest(afterResources)},prefixRetried:false,repair:false,seed:false,gatesChanged:false};
}catch(error){report={format:'darshan-d3-minio-two-pass-health-diagnosis-v1',status:'COMPARISON_INCOMPLETE',code:typeof error?.code==='string'?error.code:'UNCLASSIFIED',rounds,calls,connections,prefixRetried:false,repair:false,seed:false,gatesChanged:false};process.exitCode=2;}
finally{clearTimeout(timer);https.Agent.prototype.createConnection=original;}
console.log(JSON.stringify(report));

report.httpsRequestSource:
function request(...args) {
  let options = {};

  if (typeof args[0] === 'string') {
    const urlStr = ArrayPrototypeShift(args);
    options = urlToHttpOptions(new URL(urlStr));
  } else if (isURL(args[0])) {
    options = urlToHttpOptions(ArrayPrototypeShift(args));
  }

  if (args[0] && typeof args[0] !== 'function') {
    ObjectAssign(options, ArrayPrototypeShift(args));
  }

  options._defaultAgent = module.exports.globalAgent;
  ArrayPrototypeUnshift(args, options);

  return ReflectConstruct(ClientRequest, args);
}

